import React, { useState, useRef, useEffect } from 'react';
import { OverlayPanel } from 'primereact/overlaypanel';
import { ProductService } from '../../Demo/DataTable/service/ProductService';
import { Toast } from 'primereact/toast';
import { Button } from 'primereact/button';
import { DataTable } from 'primereact/datatable';
import { Column } from 'primereact/column';

export default function DataTableDemo() {
    const [products, setProducts] = useState(null);
    const [selectedProduct, setSelectedProduct] = useState(null);

    const selectedProductContent = selectedProduct && (
        <div className="pd10 bdr1 shadow2 uls-segment w300 mgt7">
            <div className="relative">
                <img src={'https://primefaces.org/cdn/primereact/images/product/' + selectedProduct.image} alt={selectedProduct.name}></img>
            </div>
            <div className="fxb fvc gp3 mgt5">
                <span className="text-900 font-medium font-size20">{selectedProduct.name}</span>
                <span className="text-900 font-size20 ml3">{'$' + selectedProduct.price}</span>
            </div>
            <span className="text-600 font-size14">{selectedProduct.category}</span>
        </div>
    );

    const op = useRef(null);
    const toast = useRef(null);
    const isMounted = useRef(false);

    const productSelect = (e) => {
        op.current.hide();
        toast.current.show({ severity: 'info', summary: 'Product Selected', detail:e.data.name, life: 3000 }); 
    };

    useEffect(() => {
        isMounted.current = true;
        ProductService.getProductsMini().then((data) => {
            setProducts(data);
            // Set the first product as initially selected
            if (data && data.length > 0) {
                setSelectedProduct(data[0]);
            }
        });    // eslint-disable-line react-hooks/exhaustive-deps
    }, []);

    const formatCurrency = (value) => {
        return value.toLocaleString('en-US', { style: 'currency', currency: 'USD' });
    };

    const imageBody = (rowData) => {
        return <img src={`https://primefaces.org/cdn/primereact/images/product/${rowData.image}`} alt={rowData.image} className="w100 shadow-1" />
    };

    const priceBody = (rowData) => {
        return formatCurrency(rowData.price);
    };

    return (
        <>
            <Toast ref={toast} />
            <Button type="button" icon="pi pi-search" label="Search" onClick={(e) => op.current.toggle(e)} raised />
            {selectedProductContent}
            <OverlayPanel ref={op} showCloseIcon closeOnEscape dismissable={false}>
                    <DataTable value={products} selectionMode="single" paginator rows={5} selection={selectedProduct} onSelectionChange={(e) => setSelectedProduct(e.value)} onRowClick={productSelect}>
                        <Column field="name" header="Name" sortable style={{ minWidth: '12rem' }} />
                        <Column header="Image" body={imageBody} />
                        <Column field="price" header="Price" sortable body={priceBody} style={{minWidth: '8rem'}} />
                    </DataTable>
            </OverlayPanel>
        </>
    );

}